import React, { useState } from 'react';
import './VariantDialog.css';

const VariantDialog = ({ onSubmit }) => {
  const [count, setCount] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(count);
  };

  return (
    <div className="variant-dialog-overlay">
      <div className="variant-dialog">
        <div className="variant-dialog-content">
          <h2>Propose Variants</h2>
          <form onSubmit={handleSubmit}>
            <label>
              Number of variants:
              <input
                type="number"
                value={count}
                onChange={(e) => setCount(e.target.value)}
                min="1"
                max="10"
                required
              />
            </label>
            <button type="submit" className="variant-dialog-submit-button">Submit</button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default VariantDialog;
